int numKLenSubstrNoRepeats(char *S, int k) {
  int n = strlen(S);
  if (n < k) {
    return 0;
  }
  int count[26] = {0};
  int ans = 0, distinct = 0;
  for (int i = 0; i < n; i++) {
    int idx = S[i] - 'a';
    if (count[idx] == 0) {
      distinct++;
    }
    count[idx]++;
    if (i >= k) {
      int rm = S[i - k] - 'a';
      count[rm]--;
      if (count[rm] == 0) {
        distinct--;
      }
    }
    if (i >= k - 1 && distinct == k) {
      ans++;
    }
  }
  return ans;
}

