    }
    int[] count = new int[26];
    int distinct = 0, ans = 0;
    for (int i = 0; i < n; i++) {
      int idx = S.charAt(i) - 'a';
      if (count[idx] == 0) {
        distinct++;
      }
      count[idx]++;
