}

class Solution:
    def numKLenSubstrNoRepeats(self, S: str, k: int) -> int:
        n = len(S)
        if n < k:
            return 0
        count = [0] * 26
        distinct = ans = 0
        for i in range(n):
            idx = ord(S[i]) - ord("a")
            if count[idx] == 0:
                distinct += 1
            count[idx] += 1
            if i >= k:
                rm = ord(S[i - k]) - ord("a")
                count[rm] -= 1
                if count[rm] == 0:
                    distinct -= 1
            if i >= k - 1 and distinct == k:
                ans += 1
        return ans

impl Solution {
  pub fn num_k_len_substr_no_repeats(s: String, k: i32) -> i32 {
    let b = s.as_bytes();
    let n = b.len();
    let k = k as usize;
    if n < k {
      return 0;
    }
    let mut count = [0i32; 26];
    let mut distinct = 0;
    let mut ans = 0;
    for i in 0..n {
      let idx = (b[i] - b'a') as usize;
      if count[idx] == 0 {
        distinct += 1;
      }
      count[idx] += 1;
      if i >= k {
        let rm = (b[i - k] - b'a') as usize;
        count[rm] -= 1;
        if count[rm] == 0 {
          distinct -= 1;
        }
      }
      if i >= k - 1 && distinct == k as i32 {
        ans += 1;
      }
    }
    ans
  }
}

const numKLenSubstrNoRepeats = (S: string, k: number): number => {
  const n = S.length;
  if (n < k) return 0;
  const count = new Array(26).fill(0);
  let distinct = 0;
  let ans = 0;
  for (let i = 0; i < n; i++) {
    const idx = S.charCodeAt(i) - 97;
    if (count[idx] === 0) distinct++;
    count[idx]++;
    if (i >= k) {
      const rm = S.charCodeAt(i - k) - 97;
      count[rm]--;
      if (count[rm] === 0) distinct--;
    }
    if (i >= k - 1 && distinct === k) ans++;
  }
  return ans;
};

class Solution {
public:
  int numKLenSubstrNoRepeats(string S, int k) {
    unordered_map<char, int> mp;
    int n = S.size();
    if (n < k)
      return 0;
    int ans = 0;

    for (int i = 0; i < k; i++)
      mp[S[i]]++;

    if (mp.size() == k)
      ans++;

    for (int i = k; i < n; i++) {
      mp[S[i - k]]--;
      if (!mp[S[i - k]])
        mp.erase(S[i - k]);

      mp[S[i]]++;

      if (mp.size() == k)
        ans++;
    }
    return ans;
  }
};
